Here's an example code for counting the number of times a specific word appears in a text file:

```
#include <iostream>
#include <fstream>

using namespace std;

int main() {
    ifstream inputFile;
    inputFile.open("example.txt");

    int count = 0; // initialize counter to zero

    if (inputFile.is_open()) { // check if input file is open
        while (!inputFile.eof()) { // loop through each line of the file
            string line;
            getline(inputFile, line); // read next line from file
            size_t pos = line.find("word"); // find index of "word" in line
            if (pos != string::npos) { // if found
                count++; // increment counter
            }
        }
    }

    inputFile.close(); // close input file

    cout << "The word '" << "word" << "' appears " << count << " times in the file." << endl;

    return 0;
}
```

In this program, we first declare two variables: `count` to keep track of the number of words found, and `inputFile` to hold the file object. We then use `ifstream` to open the file and set up a loop to iterate

